export type OrderStatus = "pending" | "confirmed" | "in_progress" | "completed" | "cancelled"

export type Order = {
  id: string
  customer: string
  email: string
  channel: "Website" | "Partner" | "Phone"
  status: OrderStatus
  amount: number
  createdAt: string
}

export const statusMeta: Record<OrderStatus, { label: string; tone: "neutral" | "info" | "warning" | "success" | "danger" }> = {
  pending: { label: "Pending", tone: "warning" },
  confirmed: { label: "Confirmed", tone: "info" },
  in_progress: { label: "In progress", tone: "neutral" },
  completed: { label: "Completed", tone: "success" },
  cancelled: { label: "Cancelled", tone: "danger" },
}

const first = ["Ana", "Bruno", "Clara", "David", "Emma", "Felix", "Greta", "Hugo", "Inês", "Jonas", "Lea", "Marco", "Nora", "Omar", "Paula", "Rui"]
const last = ["Silva", "Müller", "Dubois", "García", "Rossi", "de Vries", "Santos", "Schmidt", "Martin", "López"]
const channels: Order["channel"][] = ["Website", "Website", "Website", "Partner", "Phone"]
const statuses: OrderStatus[] = ["pending", "confirmed", "confirmed", "in_progress", "completed", "completed", "completed", "cancelled"]

// Deterministic pseudo-random so server and client render the same rows.
function rng(seed: number) {
  let s = seed
  return () => {
    s = (s * 16807) % 2147483647
    return (s - 1) / 2147483646
  }
}

export const orders: Order[] = (() => {
  const r = rng(42)
  const base = Date.UTC(2026, 10, 16)
  return Array.from({ length: 2000 }, (_, i) => {
    const f = first[Math.floor(r() * first.length)]
    const l = last[Math.floor(r() * last.length)]
    return {
      id: `ORD-${(22480 - i).toString()}`,
      customer: `${f} ${l}`,
      email: `${f}.${l}`.normalize("NFD").toLowerCase().replace(/[^a-z.]/g, "") + "@example.com",
      channel: channels[Math.floor(r() * channels.length)],
      status: statuses[Math.floor(r() * statuses.length)],
      amount: Math.round((80 + r() * 1400) * 100) / 100,
      createdAt: new Date(base - i * 3 * 3600 * 1000 - Math.floor(r() * 3600 * 1000)).toISOString(),
    }
  })
})()

export const currency = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR" })
export const dateTime = new Intl.DateTimeFormat("en-GB", {
  day: "2-digit",
  month: "short",
  hour: "2-digit",
  minute: "2-digit",
  timeZone: "UTC",
})

import type { ListPage, ListQuery } from "@/components/data-table/list-source"
import { type Order, orders } from "@/lib/data/orders"

/**
 * Fake back end for the Orders example: 2,000 orders in server memory, changed by the server actions.
 * A real project queries its database here with a cursor.
 */
const store: Order[] = orders.map((o) => ({ ...o }))

export const pageSize = 50

const facetColumns = ["status", "channel"] as const

function matchesSearch(o: Order, q?: string) {
  if (!q) return true
  const needle = q.trim().toLowerCase()
  return [o.id, o.customer, o.email].some((v) => v.toLowerCase().includes(needle))
}

function matchesFilters(o: Order, filters: ListQuery["filters"], except?: string) {
  return Object.entries(filters).every(
    ([column, values]) => column === except || !values.length || values.includes(String(o[column as keyof Order])),
  )
}

export function matches(o: Order, query: ListQuery) {
  return matchesSearch(o, query.q) && matchesFilters(o, query.filters)
}

function compare(a: Order, b: Order, sort: ListQuery["sort"]) {
  const id = (sort?.id ?? "createdAt") as keyof Order
  const desc = sort ? sort.desc : true
  const x = a[id]
  const y = b[id]
  const order = typeof x === "number" && typeof y === "number" ? x - y : String(x).localeCompare(String(y))
  return desc ? -order : order
}

export function queryOrders(cursor: string | null, query: ListQuery): ListPage<Order> {
  const found = store.filter((o) => matches(o, query)).sort((a, b) => compare(a, b, query.sort))
  const start = cursor ? Number(cursor) : 0
  const items = found.slice(start, start + pageSize)
  const next = start + pageSize
  // Each facet counts with the other filters applied, so picking a status doesn't zero the other statuses.
  const facets = Object.fromEntries(
    facetColumns.map((column) => {
      const counts: Record<string, number> = {}
      for (const o of store) {
        if (!matchesSearch(o, query.q) || !matchesFilters(o, query.filters, column)) continue
        const value = String(o[column])
        counts[value] = (counts[value] ?? 0) + 1
      }
      return [column, counts]
    }),
  )
  return { items, nextCursor: next < found.length ? String(next) : null, total: found.length, facets }
}

export function findOrder(id: string) {
  return store.find((o) => o.id === id)
}

export function updateOrder(id: string, changes: Partial<Omit<Order, "id">>) {
  const order = findOrder(id)
  if (order) Object.assign(order, changes)
  return order
}

export function createOrder(values: Omit<Order, "id" | "createdAt">) {
  const top = Math.max(...store.map((o) => Number(o.id.slice(4))))
  const order: Order = { ...values, id: `ORD-${top + 1}`, createdAt: new Date().toISOString() }
  store.unshift(order)
  return order
}

export function deleteOrder(id: string) {
  const index = store.findIndex((o) => o.id === id)
  if (index >= 0) store.splice(index, 1)
}

/** A customer of the example: whoever placed orders with the same email. */
export function customerSlug(order: Pick<Order, "email">) {
  return order.email.split("@")[0]
}

export function findCustomer(slug: string) {
  const orders = store.filter((o) => customerSlug(o) === slug)
  if (!orders.length) return undefined
  return {
    slug,
    name: orders[0].customer,
    email: orders[0].email,
    orders: [...orders].sort((a, b) => b.createdAt.localeCompare(a.createdAt)),
    total: orders.filter((o) => o.status !== "cancelled").reduce((sum, o) => sum + o.amount, 0),
  }
}

export type DailyPoint = { date: string; revenue: number; orders: number }

function rng(seed: number) {
  let s = seed
  return () => {
    s = (s * 16807) % 2147483647
    return (s - 1) / 2147483646
  }
}

export const daily: DailyPoint[] = (() => {
  const r = rng(7)
  const end = Date.UTC(2026, 10, 16)
  return Array.from({ length: 90 }, (_, i) => {
    const d = new Date(end - (89 - i) * 86400000)
    const weekend = d.getUTCDay() === 0 || d.getUTCDay() === 6
    const trend = 3200 + i * 22
    const revenue = Math.round(trend * (weekend ? 1.25 : 1) * (0.8 + r() * 0.4))
    return { date: d.toISOString().slice(0, 10), revenue, orders: Math.round(revenue / 410) }
  })
})()

const total90 = daily.reduce((s, d) => s + d.revenue, 0)
export const byChannel = [
  { channel: "Website", share: 0.57 },
  { channel: "Partners", share: 0.29 },
  { channel: "Phone", share: 0.1 },
  { channel: "Walk-in", share: 0.04 },
].map((c) => ({ channel: c.channel, revenue: Math.round(total90 * c.share) }))

const last30 = daily.slice(-30)
const prev30 = daily.slice(-60, -30)
const sum = (xs: DailyPoint[], k: "revenue" | "orders") => xs.reduce((s, d) => s + d[k], 0)
const pct = (a: number, b: number) => ((a - b) / b) * 100

const revenue = sum(last30, "revenue")
const ordersCount = sum(last30, "orders")
const prevRevenue = sum(prev30, "revenue")
const prevOrders = sum(prev30, "orders")

const eur = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR", maximumFractionDigits: 0 })
const eur2 = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR" })
const int = new Intl.NumberFormat("en-GB")

export const kpis = [
  { label: "Revenue", value: eur.format(revenue), delta: pct(revenue, prevRevenue), hint: "vs previous 30 days", series: last30.map((d) => d.revenue) },
  { label: "Orders", value: int.format(ordersCount), delta: pct(ordersCount, prevOrders), hint: "vs previous 30 days", series: last30.map((d) => d.orders) },
  { label: "Average order", value: eur2.format(revenue / ordersCount), delta: pct(revenue / ordersCount, prevRevenue / prevOrders), hint: "vs previous 30 days", series: null },
  { label: "Cancellation rate", value: "4.2%", delta: -1.3, hint: "lower is better", series: null, invert: true },
] as const

"use client"

import * as React from "react"
import { Area, AreaChart, CartesianGrid, XAxis, YAxis } from "recharts"

import { Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card"
import { type ChartConfig, ChartContainer, ChartTooltip, ChartTooltipContent } from "@/components/ui/chart"
import { ToggleGroup, ToggleGroupItem } from "@/components/ui/toggle-group"
import { daily } from "@/lib/data/metrics"

const config = { revenue: { label: "Revenue", color: "var(--chart-1)" } } satisfies ChartConfig

const ranges = { "7d": 7, "30d": 30, "90d": 90 } as const
type Range = keyof typeof ranges

const eur = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR", maximumFractionDigits: 0 })
const eurCompact = new Intl.NumberFormat("en-GB", { style: "currency", currency: "EUR", notation: "compact" })
const day = new Intl.DateTimeFormat("en-GB", { day: "numeric", month: "short", timeZone: "UTC" })

export function RevenueChart() {
  const [range, setRange] = React.useState<Range>("30d")
  const data = daily.slice(-ranges[range])
  const total = data.reduce((s, d) => s + d.revenue, 0)

  return (
    <Card className="gap-4">
      <CardHeader>
        <CardTitle>Revenue</CardTitle>
        <CardDescription>
          <span className="font-medium text-foreground tabular-nums">{eur.format(total)}</span> in the last {ranges[range]} days
        </CardDescription>
        <CardAction>
          <ToggleGroup
            type="single"
            variant="outline"
            size="sm"
            value={range}
            onValueChange={(v) => v && setRange(v as Range)}
            aria-label="Time range"
          >
            {Object.keys(ranges).map((r) => (
              <ToggleGroupItem key={r} value={r} className="px-2.5 text-xs">
                {r}
              </ToggleGroupItem>
            ))}
          </ToggleGroup>
        </CardAction>
      </CardHeader>
      <CardContent className="px-2 sm:px-4">
        <ChartContainer config={config} className="aspect-auto h-64 w-full">
          <AreaChart data={data} margin={{ left: 4, right: 8, top: 8 }} accessibilityLayer>
            <defs>
              <linearGradient id="fill-revenue" x1="0" y1="0" x2="0" y2="1">
                <stop offset="0%" stopColor="var(--color-revenue)" stopOpacity={0.25} />
                <stop offset="100%" stopColor="var(--color-revenue)" stopOpacity={0.02} />
              </linearGradient>
            </defs>
            <CartesianGrid vertical={false} strokeDasharray="0" />
            <XAxis
              dataKey="date"
              tickLine={false}
              axisLine={false}
              tickMargin={8}
              minTickGap={32}
              tickFormatter={(v: string) => day.format(new Date(v))}
            />
            <YAxis
              tickLine={false}
              axisLine={false}
              width={52}
              tickFormatter={(v: number) => eurCompact.format(v)}
            />
            <ChartTooltip
              cursor={{ stroke: "var(--border)", strokeWidth: 1 }}
              content={
                <ChartTooltipContent
                  indicator="line"
                  labelFormatter={(v) => day.format(new Date(String(v)))}
                  formatter={(value) => (
                    <div className="flex w-full justify-between gap-4">
                      <span className="text-muted-foreground">Revenue</span>
                      <span className="font-mono font-medium tabular-nums">{eur.format(Number(value))}</span>
                    </div>
                  )}
                />
              }
            />
            <Area
              dataKey="revenue"
              type="monotone"
              stroke="var(--color-revenue)"
              strokeWidth={2}
              fill="url(#fill-revenue)"
              activeDot={{ r: 4, strokeWidth: 2, stroke: "var(--card)" }}
            />
          </AreaChart>
        </ChartContainer>
      </CardContent>
    </Card>
  )
}

"use client"

import type { ColumnDef } from "@tanstack/react-table"
import { MoreHorizontal } from "lucide-react"
import Link from "next/link"
import { useRouter } from "next/navigation"
import * as React from "react"
import { toast } from "sonner"

import { ColumnHeader } from "@/components/data-table/column-header"
import { DataTable, useIsCardCell } from "@/components/data-table/data-table"
import { DataTableToolbar } from "@/components/data-table/data-table-toolbar"
import { markItemChanged } from "@/components/data-table/list-updates"
import { multiValueFilter } from "@/components/data-table/faceted-filter"
import { StatusBadge } from "@/components/status-badge"
import { Button } from "@/components/ui/button"
import { Checkbox } from "@/components/ui/checkbox"
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu"
import { type Order, currency, dateTime, statusMeta } from "@/lib/data/orders"

import { fetchOrder, fetchOrdersPage, removeOrder } from "./actions"

const copyOrderId = (order: Order) => navigator.clipboard?.writeText(order.id)
const deleteOrder = async (order: Order) => {
  await removeOrder(order.id)
  toast.success(`${order.id} deleted`)
  // No dialog open: the row is fetched again at once and stays, marked as deleted.
  markItemChanged("orders", order.id)
}

export const orderHref = (order: Order) => `/orders/${order.id}`

function OrderLink({ order }: { order: Order }) {
  // Inside a card the whole card is the link, so the ID is plain text there.
  const inCard = useIsCardCell()
  const className = "rounded font-mono text-xs font-medium"
  if (inCard) return <span className={className}>{order.id}</span>
  return (
    <Link
      href={orderHref(order)}
      data-slot="row-link"
      className={`${className} inline-flex items-center hover:underline focus-visible:ring-2 focus-visible:ring-ring focus-visible:outline-none`}
    >
      {order.id}
    </Link>
  )
}

function buildColumns(open: (o: Order) => void, edit: (o: Order) => void): ColumnDef<Order>[] {
  return [
    {
      id: "select",
      size: 36,
      header: ({ table }) => (
        <Checkbox
          checked={table.getIsAllPageRowsSelected() || (table.getIsSomePageRowsSelected() && "indeterminate")}
          onCheckedChange={(v) => table.toggleAllPageRowsSelected(!!v)}
          aria-label="Select all loaded"
        />
      ),
      cell: ({ row }) => (
        <Checkbox
          checked={row.getIsSelected()}
          onCheckedChange={(v) => row.toggleSelected(!!v)}
          onClick={(e) => e.stopPropagation()}
          aria-label={`Select ${row.original.id}`}
        />
      ),
      enableSorting: false,
      enableHiding: false,
    },
    {
      accessorKey: "id",
      header: ({ column }) => <ColumnHeader column={column} title="Order" />,
      meta: { mobile: "subtitle", title: "Order" },
      cell: ({ row }) => <OrderLink order={row.original} />,
      enableHiding: false,
    },
    {
      accessorKey: "customer",
      meta: { mobile: "title", title: "Customer" },
      header: ({ column }) => <ColumnHeader column={column} title="Customer" />,
      cell: ({ row }) => (
        <div className="min-w-0">
          <div className="truncate font-medium">{row.original.customer}</div>
          <div className="truncate text-xs text-muted-foreground">{row.original.email}</div>
        </div>
      ),
    },
    {
      accessorKey: "status",
      meta: { mobile: "status" },
      header: "Status",
      cell: ({ row }) => {
        const m = statusMeta[row.original.status]
        return <StatusBadge tone={m.tone}>{m.label}</StatusBadge>
      },
      filterFn: multiValueFilter,
    },
    {
      accessorKey: "channel",
      header: "Channel",
      cell: ({ row }) => <span className="text-muted-foreground">{row.original.channel}</span>,
      filterFn: multiValueFilter,
    },
    {
      accessorKey: "createdAt",
      meta: { mobile: "subtitle", title: "Created" },
      header: ({ column }) => <ColumnHeader column={column} title="Created" />,
      cell: ({ row }) => (
        <time dateTime={row.original.createdAt} className="text-muted-foreground">
          {dateTime.format(new Date(row.original.createdAt))}
        </time>
      ),
    },
    {
      accessorKey: "amount",
      meta: { mobile: "value", title: "Amount" },
      header: ({ column }) => <ColumnHeader column={column} title="Amount" align="right" />,
      cell: ({ row }) => <div className="text-right font-medium">{currency.format(row.original.amount)}</div>,
    },
    {
      id: "actions",
      size: 44,
      enableHiding: false,
      cell: ({ row }) => (
        <div className="flex justify-end">
          <DropdownMenu>
            <DropdownMenuTrigger asChild>
              <Button
                variant="ghost"
                size="icon-sm"
                onClick={(e) => e.stopPropagation()}
                aria-label={`Actions for ${row.original.id}`}
              >
                <MoreHorizontal />
              </Button>
            </DropdownMenuTrigger>
            <DropdownMenuContent align="end" onClick={(e) => e.stopPropagation()}>
              <DropdownMenuItem onSelect={() => open(row.original)}>View details</DropdownMenuItem>
              <DropdownMenuItem onSelect={() => edit(row.original)}>Edit</DropdownMenuItem>
              <DropdownMenuItem onSelect={() => copyOrderId(row.original)}>
                Copy order ID
              </DropdownMenuItem>
              <DropdownMenuSeparator />
              <DropdownMenuItem
                variant="destructive"
                onSelect={() => deleteOrder(row.original)}
              >
                Delete
              </DropdownMenuItem>
            </DropdownMenuContent>
          </DropdownMenu>
        </div>
      ),
    },
  ]
}

const statusOptions = Object.entries(statusMeta).map(([value, m]) => ({ value, label: m.label }))
const channelOptions = ["Website", "Partner", "Phone"].map((v) => ({ value: v, label: v }))

const count = new Intl.NumberFormat("en-US")
const ordersLabels = {
  total: (loaded: number, total: number) =>
    `${count.format(loaded)} of ${count.format(total)} ${total === 1 ? "order" : "orders"}`,
}

export function OrdersTable() {
  const router = useRouter()
  const columns = React.useMemo(
    () =>
      buildColumns(
        (o) => router.push(orderHref(o)),
        (o) => router.push(`${orderHref(o)}/edit`),
      ),
    [router],
  )

  return (
    <>
      <DataTable
        label="Orders"
        columns={columns}
        fetchPage={fetchOrdersPage}
        resource="orders"
        fetchItem={fetchOrder}
        getRowHref={orderHref}
        labels={ordersLabels}
        toolbar={(table, density, setDensity) => (
          <DataTableToolbar
            table={table}
            density={density}
            onDensityChange={setDensity}
            search={{ label: "Search orders", placeholder: "Search orders…" }}
            filters={[
              { column: "status", title: "Status", options: statusOptions },
              { column: "channel", title: "Channel", options: channelOptions },
            ]}
          />
        )}
      />
    </>
  )
}

"use server"

import type { ListQuery } from "@/components/data-table/list-source"
import type { Order } from "@/lib/data/orders"
import { createOrder, deleteOrder, findOrder, matches, queryOrders, updateOrder } from "@/lib/data/orders-store"

const latency = () => new Promise((resolve) => setTimeout(resolve, 150))

export async function fetchOrdersPage({ cursor, query }: { cursor: string | null; query: ListQuery }) {
  await latency()
  return queryOrders(cursor, query)
}

export async function fetchOrder(id: string, query: ListQuery) {
  await latency()
  const item = findOrder(id)
  return item ? { item: { ...item }, matches: matches(item, query) } : null
}

export type OrderValues = {
  customer: string
  email: string
  amount: number
  channel: Order["channel"]
  status: Order["status"]
}

/** Creates an order, or updates it when `id` is given. Returns the saved order. */
export async function saveOrder(id: string | null, values: OrderValues) {
  await latency()
  return id ? updateOrder(id, values) : createOrder(values)
}

export async function removeOrder(id: string) {
  await latency()
  deleteOrder(id)
}

import type { Metadata } from "next"

import { RoutedPage } from "@/components/routed-dialog/routed-dialog"

import { OrderForm } from "../order-form"

export const metadata: Metadata = { title: "New order" }

// Opened directly or after F5; from the list the same form opens in the Dialog roteado.
